/**
 * Post-build static shell injection for FCP.
 * Injects visible HTML into #root for / and /tech-news before React boots.
 * No headless browser required — uses build-time tech-news-latest.json.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const BUILD_DIR = path.join(ROOT, 'build');
const SNAPSHOT_PATH = path.join(BUILD_DIR, 'tech-news-latest.json');

/**
 * Generated by scripts/generate-hero-poster.mjs, and the single source of truth
 * for where the bust sits — the same file HeroHeadCanvas.tsx imports, so the
 * shell's poster and React's poster cannot land in different places.
 */
const POSTER = JSON.parse(
  fs.readFileSync(path.join(ROOT, 'src/features/hero-3d/posterMetrics.json'), 'utf8'),
);

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function readSnapshotArticles() {
  try {
    if (!fs.existsSync(SNAPSHOT_PATH)) return [];
    const json = JSON.parse(fs.readFileSync(SNAPSHOT_PATH, 'utf8'));
    return Array.isArray(json?.data?.articles) ? json.data.articles.slice(0, 6) : [];
  } catch {
    return [];
  }
}

/**
 * Design tokens, mirrored from src/styles/globals.css.
 *
 * The shell is written with INLINE styles on purpose: it must paint before the
 * render-blocking stylesheet arrives, so it cannot depend on Tailwind classes.
 */
const T = {
  bg: '#0a0a0b',
  fg: '#ededea',
  signal: '#ff4a1c',
  hairline: 'rgba(255,255,255,0.09)',
  hairlineStrong: 'rgba(255,255,255,0.2)',
  ink45: 'rgba(237,237,234,0.45)',
  ink62: 'rgba(237,237,234,0.62)',
  sans: "'Space Grotesk',ui-sans-serif,system-ui,-apple-system,sans-serif",
  mono: "'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,monospace",
};

/**
 * The home shell is a visual match for <HeroSection>, NOT a generic placeholder.
 *
 * Why this matters more than any byte-level optimisation: main.tsx boots with
 * `createRoot().render()`, which DISCARDS whatever is in #root. The shell is
 * therefore a throwaway paint — and while it was showing stale pre-redesign copy
 * in system-ui, the real hero (and the webfonts it needs) did not exist until
 * React had downloaded, parsed and rendered. Measured on production: the `latin`
 * font subsets were not even requested until 3,503 ms, and LCP carried a
 * 3,190 ms element render delay against a 0 ms TTFB.
 *
 * Matching the real hero makes the first paint the final paint. React still
 * replaces the DOM, but the pixels do not change, so LCP lands at FCP.
 *
 * ⚠️ This markup duplicates src/sections/HeroSection.tsx and can drift.
 * tests/prerender-home-shell.test.mjs guards the headline text.
 */
/**
 * The sticky header, replicated at its exact rendered height (62 px: py-4 plus
 * an 11px/1 mono row with an 8px-padded button).
 *
 * It has to be here even though it is chrome rather than content: <SiteHeader>
 * is `position: sticky`, so it sits in normal flow and occupies real height.
 * A shell without it would render the hero 62 px too high and React would shove
 * everything down on hydration — turning a currently-perfect CLS of 0 into a
 * visible jump.
 */
function headerShell() {
  const link = `color:rgba(237,237,234,0.55);text-decoration:none`;
  const nav = ['SYSTEMS', 'WORK', 'NEWS', 'SERVICES', 'TECH NEWS']
    .map((l) => `<span style="${link}">${l}</span>`)
    .join('');

  return `<div style="position:sticky;top:0;z-index:50;border-bottom:1px solid ${T.hairline};background:rgba(10,10,11,0.82)">
  <div style="margin:0 auto;max-width:1440px;display:grid;grid-template-columns:1fr auto;align-items:center;column-gap:24px;row-gap:12px;padding:16px clamp(18px,4vw,52px);font:500 11px/1 ${T.mono};letter-spacing:0.14em">
    <span style="color:${T.fg}">CEM KÖYLÜOĞLU</span>
    <span style="display:flex;align-items:center;gap:14px">
      <span style="border:1px solid ${T.hairlineStrong};padding:8px 11px;color:${T.fg}">TR</span>
    </span>
    <span style="display:none">${nav}</span>
  </div>
</div>`;
}

function homeShell() {
  const label = `font:500 11px/1.7 ${T.mono};letter-spacing:0.12em;color:${T.signal}`;
  const meta = `margin:0;font:400 11px/1.7 ${T.mono};color:${T.ink45}`;
  const cta = `display:inline-block;font:500 11px/1 ${T.mono};letter-spacing:0.1em;padding:14px 20px;text-decoration:none`;

  /*
    The hero's 3D bust, as a static image.

    It is written as plain markup inside #root rather than a <link rel=preload>
    so the browser's preload scanner picks it up during the initial HTML parse —
    and so it is scoped to this route: /tech-news gets its own shell and never
    pays for it.
  */
  const posterStyle = Object.entries(POSTER.style)
    .map(([key, value]) => `${key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}:${value}`)
    .join(';');
  const poster =
    `<img src="/models/${POSTER.file}" alt="" aria-hidden="true" ` +
    `width="${POSTER.pixels.width}" height="${POSTER.pixels.height}" ` +
    `decoding="async" fetchpriority="high" ` +
    `style="position:absolute;${posterStyle}">`;

  return `
<div id="prerender-shell" style="background:radial-gradient(120% 80% at 50% 4%,#17181b 0%,${T.bg} 60%);color:${T.fg};font-family:${T.sans};overflow:hidden">
  ${headerShell()}
  <div style="position:relative;overflow:hidden;padding-top:clamp(28px,5vh,64px)">
  ${poster}
  <div style="position:relative;margin:0 auto;max-width:1440px;padding-left:clamp(18px,4vw,52px);padding-right:clamp(18px,4vw,52px)">
    <div style="display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px">
      <div style="max-width:230px">
        <div style="${label}">01 / STATUS</div>
        <p style="${meta}">Dublin, Ireland — open to full-time AI/ML engineering roles and freelance builds.</p>
      </div>
      <div style="max-width:250px;text-align:right">
        <div style="${label}">02 / FIELD</div>
        <p style="${meta}">Deepfake detection · computer vision · RAG · agentic workflows · Azure &amp; M365</p>
      </div>
    </div>

    <div style="height:clamp(260px,48vh,430px)" aria-hidden="true"></div>

    <h1 style="margin:0;font:700 clamp(40px,8.2vw,112px)/0.86 ${T.sans};letter-spacing:-0.05em;text-wrap:balance">AI systems<br>that survive<br><span style="color:${T.signal}">production.</span></h1>

    <div style="margin-top:clamp(24px,3vh,40px);display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:26px;border-top:1px solid ${T.hairline};padding-top:18px;padding-bottom:clamp(28px,4vh,44px)">
      <p style="margin:0;max-width:440px;font:400 clamp(13px,1.1vw,15px)/1.6 ${T.sans};color:${T.ink62}">AI Engineer &amp; System Operations Specialist. MSc Artificial Intelligence, First Class Honours — National College of Ireland.</p>
      <div style="display:flex;flex-wrap:wrap;gap:10px">
        <a href="#contact" style="${cta};background:${T.signal};color:${T.bg}">HIRE ME →</a>
        <a href="#work" style="${cta};border:1px solid ${T.hairlineStrong};color:${T.fg}">SEE THE WORK</a>
      </div>
    </div>
    </div>
  </div>
</div>`.trim();
}

function techNewsShell(articles) {
  const items = articles
    .map((article) => {
      const title = escapeHtml(article.title);
      const href = `/tech-news/${escapeHtml(article.slug)}`;
      const desc = escapeHtml((article.description || '').slice(0, 140));
      const category = escapeHtml(article.category || 'Tech');
      return `<li style="margin:0 0 1.25rem;list-style:none">
  <a href="${href}" style="color:inherit;text-decoration:none">
    <span style="display:inline-block;font-size:0.75rem;opacity:0.7;margin-bottom:0.25rem">${category}</span>
    <strong style="display:block;font-size:1.1rem;line-height:1.3;margin-bottom:0.35rem">${title}</strong>
    <span style="display:block;opacity:0.75;font-size:0.9rem">${desc}</span>
  </a>
</li>`;
    })
    .join('\n');

  return `
<div id="prerender-shell" style="min-height:100vh;background:#0a0a0b;color:#f4f4f5;font-family:system-ui,sans-serif;padding:2rem 1.25rem;max-width:48rem;margin:0 auto">
  <p style="font-size:0.85rem;letter-spacing:0.08em;text-transform:uppercase;opacity:0.7;margin:0 0 0.5rem">Tech News</p>
  <h1 style="font-size:clamp(1.5rem,4vw,2.25rem);margin:0 0 1.5rem">Latest Tech News</h1>
  <ul style="margin:0;padding:0">${items || '<li style="list-style:none;opacity:0.8">Loading curated technology articles…</li>'}</ul>
</div>`.trim();
}

/**
 * Preload the one webfont that renders the largest text on the page.
 *
 * @fontsource's @font-face rules are compiled INTO the CSS bundle, so the
 * browser cannot discover a single font file until that render-blocking
 * stylesheet has arrived and parsed. Preloading breaks that serial chain for
 * the headline face specifically.
 *
 * Only Space Grotesk 700 latin. The other nine faces (129 KB in total) stay
 * discovery-order: preloading is a promise that the file is needed immediately,
 * and spending mobile bandwidth on all of them would compete with the very
 * paint it is meant to accelerate. The header logo's latin-ext face is
 * deliberately not here — "KÖYLÜOĞLU" is 11px chrome, not content.
 *
 * The filename is content-hashed, so this has to run after the bundle exists.
 */
function injectFontPreload(html) {
  const assets = path.join(BUILD_DIR, 'assets');
  if (!fs.existsSync(assets)) return html;

  const face = fs
    .readdirSync(assets)
    .find((f) => /^space-grotesk-latin-700-normal-.*\.woff2$/.test(f));
  if (!face) {
    console.warn('⚠️  Space Grotesk 700 not found — skipping font preload');
    return html;
  }

  // crossorigin is REQUIRED on font preloads: fonts are always fetched in CORS
  // mode, and a non-CORS preload would be downloaded and then discarded.
  const link =
    `<link rel="preload" as="font" type="font/woff2" crossorigin ` +
    `href="/assets/${face}" />`;
  return html.replace('</head>', `  ${link}\n  </head>`);
}

function injectRoot(html, shellHtml) {
  if (!html.includes('id="root"')) {
    throw new Error('build/index.html missing #root');
  }
  // Prefer empty root replacement; Vite emits <div id="root"></div>
  if (html.includes('<div id="root"></div>')) {
    return html.replace(
      '<div id="root"></div>',
      `<div id="root">${shellHtml}</div>`,
    );
  }
  return html.replace(
    /<div id="root"[^>]*>[\s\S]*?<\/div>/,
    `<div id="root">${shellHtml}</div>`,
  );
}

function writeHtml(filePath, html) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, html, 'utf8');
}

function prerenderRoutes() {
  const indexPath = path.join(BUILD_DIR, 'index.html');
  if (!fs.existsSync(indexPath)) {
    console.warn('⚠️  build/index.html not found — skip prerender');
    return;
  }

  const baseHtml = injectFontPreload(fs.readFileSync(indexPath, 'utf8'));
  const articles = readSnapshotArticles();

  const homeHtml = injectRoot(baseHtml, homeShell());
  writeHtml(indexPath, homeHtml);
  console.log('✅ Prerendered / (index.html shell)');

  const techNewsHtml = injectRoot(baseHtml, techNewsShell(articles));
  // Point canonical-ish title for list page
  const techNewsWithTitle = techNewsHtml.replace(
    /<title>[^<]*<\/title>/,
    '<title>Tech News | Cem Koyluoglu</title>',
  );
  writeHtml(path.join(BUILD_DIR, 'tech-news', 'index.html'), techNewsWithTitle);
  console.log(`✅ Prerendered /tech-news (${articles.length} article teasers)`);
}

try {
  prerenderRoutes();
} catch (error) {
  console.error('Prerender failed:', error.message);
  // Non-fatal: deploy should still succeed
  process.exitCode = 0;
}
